// main's pull-view adapter clears the previous source before asking a new provider.\n  toolDisplayImage.Show(null);toolDisplayRecord.Show(null);toolDisplayList.Show(null);\n  toolDisplayImage.Visibility=toolDisplayRecord.Visibility=toolDisplayList.Visibility=Visibility.Collapsed;\n  Preview.Visibility=PreviewImageName.Visibility=Visibility.Visible;\n  EmptyImage.Visibility=Preview.Source is null?Visibility.Visible:Visibility.Collapsed;\n  var provider=node is null?null:plugins.Find(node.ModuleId) as IToolDisplayProvider;\n  ToolDisplayFrame? frame=null;\n  try{\n   if(provider is not null&&node is not null&&results.ContainsKey(node.Id))frame=provider.LastDisplay(node,doc.BaseDirectory,executionScope.ForProcedure(doc.CurrentProcedureId));\n   if(frame is not null&&node is not null)frame=ToolConfigurationDisplaySubscriptions.ApplyPositions(frame,node,doc.CurrentProcedureId,(source,port)=>results.GetValueOrDefault(source)?.Outputs.GetValueOrDefault(port));\n  }\n  catch(Exception error){if(!Current())return;StatusText.Text=\"结果显示失败：\"+error.Message;} // Independent host diagnostic; not native exception parity.\n  if(!Current())return;\n  toolRecordTab.Visibility=provider is null?Visibility.Collapsed:Visibility.Visible;\n  toolListTab.Visibility=provider is null?Visibility.Collapsed:Visibility.Visible;\n  if(provider is null&&DisplayTabs.SelectedIndex>1)DisplayTabs.SelectedIndex=0;\n  toolDisplayImage.Show(frame);toolDisplayRecord.Show(frame);toolDisplayList.Show(frame);\n  bool overlay=frame is not null&&DisplayTabs.SelectedIndex==0;\n  toolDisplayImage.Visibility=overlay?Visibility.Visible:Visibility.Collapsed;\n  Preview.Visibility=overlay?Visibility.Collapsed:Visibility.Visible;\n  PreviewImageName.Visibility=overlay?Visibility.Collapsed:Visibility.Visible;\n  if(overlay)EmptyImage.Visibility=Visibility.Collapsed;\n  ImagePreviewPane.Visibility=DisplayTabs.SelectedIndex==0?Visibility.Visible:Visibility.Collapsed;\n  ModuleResultsGrid.Visibility=DisplayTabs.SelectedIndex==1?Visibility.Visible:Visibility.Collapsed;\n  toolDisplayRecord.Visibility=provider is not null&&DisplayTabs.SelectedIndex==2?Visibility.Visible:Visibility.Collapsed;\n  toolDisplayList.Visibility=provider is not null&&DisplayTabs.SelectedIndex==3?Visibility.Visible:Visibility.Collapsed;\n  toolDisplayImage.LayoutTransform=new ScaleTransform(previewScale,previewScale);\n }","evidenceType":"current-source","binaryIdentity":"not revalidated in this slice"},{"path":"src/VisionEditor/MainWindow.FrameworkExecutionOwnership.cs","member":"Current owner stamp host adapter","sha256":"5b628d95732f56404fb07fc4eccd7458666ec0015901b66fb3596905d91b0be1","start":11,"end":18,"excerpt":"    ExecutionOwnerStamp CaptureExecutionOwner() => executionOwnerEpoch.Capture(doc.SolutionId,executionScope);\n    bool IsCurrentExecutionOwner(ExecutionOwnerStamp stamp) => !windowClosed &&\n        executionOwnerEpoch.IsCurrent(stamp,doc.SolutionId,executionScope);\n    void DispatchWorkflowCallback(Action callback)\n    {\n        if(windowClosed)return;\n        if(Dispatcher.CheckAccess())callback();\n        else _=Dispatcher.BeginInvoke(callback);","evidenceType":"current-source","binaryIdentity":"not revalidated in this slice"},{"path":"src/VisionEditor.Core/ExecutionOwnerEpoch.cs","member":"Current stamp capture and validity predicates","sha256":"3a428fe53f2d23de3988fd363efde08134abab0ffa97ce9a303dcc88a6554bfb","start":9,"end":30,"excerpt":"    public ExecutionOwnerStamp Capture(string solutionId, object scopeOwner)\n    {\n        ArgumentNullException.ThrowIfNull(solutionId);\n        ArgumentNullException.ThrowIfNull(scopeOwner);\n        return new(this, Interlocked.Read(ref generation), solutionId, scopeOwner);\n    }\n\n    public bool IsCurrent(ExecutionOwnerStamp stamp, string solutionId, object scopeOwner) =>\n        Volatile.Read(ref closed) == 0 && ReferenceEquals(stamp.Epoch, this)\n        && stamp.Generation == Interlocked.Read(ref generation)\n        && string.Equals(stamp.SolutionId, solutionId, StringComparison.Ordinal)\n        && ReferenceEquals(stamp.ScopeOwner, scopeOwner);\n\n    /// \u003csummary>Call before replacing or disposing the old execution scope, even for identical document IDs.\u003c/summary>\n    public void Invalidate() => Interlocked.Increment(ref generation);\n\n    public void Close()\n    {\n        Interlocked.Exchange(ref closed, 1);\n        Invalidate();\n    }\n}","evidenceType":"current-source","binaryIdentity":"not revalidated in this slice"}],"unknowns":["LastDisplay为同步调用，仍可能由provider重入造成新请求；此门只拒绝旧提交，不证明native provider释放、跨线程所有UI访问或原历史帧回放等价。","原HRE03 Background查询重新读取m_CurrentInfo，与此独立owner/request方案保持分别标注。"],"operationComplete":false,"stages":{"classification":"independent-implementation","sourceRecovery":"current-source-slice; original behavior not inferred","runtimeCorroboration":"not-established-by-this-static-audit","currentExecution":"not-executed-by-this-audit","currentImplementation":"independent-current-source-slice; not VM parity","hostAcceptance":"separate; not established or counted by this audit","wholeFeatureClosure":"not-inferred"}},{"id":"HRC03","classification":"independent-implementation","relation":"research: module result history, current-result selection and help","from":"当前Attach / ReplaceExecutionScope / OnClosed","to":"物理解订阅与已排队委托的二次门","behavior":"DetachExecutionScope从subscribedExecutionScope移除两个保留delegate实例并置空字段。Attach先Detach，再捕获owner，安装ProcedureRefreshRequested/ProcedureRunRequested处理器；两者排Dispatcher.BeginInvoke后在实际执行时再次比较scope引用和ScopeId。refresh另要求当前流程相同；run另拒windowClosed/activeRun，并查请求流程确含NodeId才RunProcedure。Replace先Invalidate再Detach，清计数/调试/配置/结果，Dispose旧scope、新建并Attach。OnClosed先Close epoch/Detach/doc.Dispose，再置windowClosed，关callback queue/配置/scope等；源码不是try/finally，任一步抛错不保证余下清理完成。取消旧run与解事件也不等于撤销Dispatcher已排队项，因此委托内owner门独立保留。","refs":[{"path":"src/VisionEditor/ToolExecutionScope.cs","member":"Current physical detach and queued delegate admission","sha256":"bb92b32267ff332