function showCoreStages(e,host){const s=e.stages;if(!s)return;const labels={'finite-source-slice; retain each reference evidence type and identity limits':'已定位有限源码片段；证据类型及原件身份限制见引用','current-source-slice; original behavior not inferred':'本行仅定位当前源码，不据此推定原版行为','unresolved':'待取证','not-established-by-this-static-audit':'本静态专题未建立运行佐证','independent-current-source-slice; not VM parity':'当前独立实现片段，不等于原版等价','not-inferred-from-this-row':'本行不推定整体实施状态','separate; not established or counted by this audit':'另列，本静态专题未建立且不计入实施进度','not-inferred':'本行不推定完整功能完成','not-executed-by-this-audit':'本专题没有执行当前实现','isolated-current-production-source; audit scope only, not every row or full algorithm proof':'隔离编译当前真实源码并执行有限夹具；不等于部署DLL、本行全部分支或完整算法已验证'};const box=el('details');box.append(el('summary','源码、运行佐证、当前实现与宿主验收分列'),el('p','此状态表属于独立研究组织，不增加原版行为边。'));for(const [key,title] of [['sourceRecovery','源码取证'],['runtimeCorroboration','本轮原版运行佐证'],['currentExecution','本专题当前执行范围'],['currentImplementation','当前实现'],['hostAcceptance','宿主验收'],['wholeFeatureClosure','完整功能闭合']])box.append(el('p',title+'：'+(labels[s[key]]||s[key])));host.append(box)}
