function showCoreFinding(b,e){history.replaceState(null,'','#audit/'+encodeURIComponent(b.id)+'/'+encodeURIComponent(e.id));const d=document.getElementById('detail');d.replaceChildren(el('h2',b.title+' › '+e.id),el('p',e.classification+' · '+e.from+' → '+e.to),el('p',e.behavior),el('p','核心定位是独立研究导航；完整入口、同实例与运行绑定仍未证明。'));showCoreStages(e,d);const a=el('a','打开原专题中的精确关系 ↗');a.href=b.path+'#'+e.id;d.append(a,el('p',b.meaning));for(const u of e.unknowns||[])d.append(el('p','待追：'+u));for(const r of e.refs)showRef(r,d);showCoreExtensions(b.id,e.id,d);for(const p of b.extendsUnknowns||[]){const a=el('a','此前仍开放的边界：'+p.audit+' / '+p.id);a.href='#audit/'+encodeURIComponent(p.audit)+'/'+encodeURIComponent(p.id);d.append(el('br'),a)}}
function showCoreExtensions(audit,id,host){const children=model.core.supplemental.branches.filter(b=>(b.extendsUnknowns||[]).some(p=>p.audit===audit&&p.id===id));if(!children.length)return;host.append(el('p','后续有限补证（此处原未知仍保留）：'));for(const b of children){const a=el('a',b.title+' ↗');a.href='#audit/'+encodeURIComponent(b.id)+'/'+encodeURIComponent(b.findings[0].id);host.append(a,el('br'))}}
function showUpstreamRelated(ids,host){if(!ids.some(id=>['render-entry','shape-adapter','render-control','render-backend','text-producer','blob-ui'].includes(id)))return;host.append(el('h3','显示合同的导出支路与原生装配取证'),el('p','下面是共享图形/文字数据的研究导航；屏幕呈现不自动调用文件导出，也不证明相同活实例或特定DLL已装载。'));showCoreBranches(b=>['image-export-entry-audit','export-text-rendering-audit','rendering-native-loader-audit'].includes(b.id),host)}
function showRegionDataContext(region,host){const context=model.core.dataArchitecture.entryContext,ids=context.regionFacts[region]||[],rendered=new Set();if(!ids.length)return rendered;const section=el('section');section.append(el('h3','这个区域的数据链：参数、图像与模块结果'),el('p',context.meaning),el('p','下列是按操作选择的研究上下文。工具专属事实只证明其明示工具和分支；不证明该区域全部入口或全部工具已接入，也不把原版两条显示路径并成一个实例。'));for(const kind of ['source-confirmed','independent-implementation','unknown']){const selected=ids.map(id=>context.facts.find(f=>f.id===id)).filter(f=>f.classification===kind);if(!selected.length)continue;section.append(el('h4',kind==='source-confirmed'?'原版：源码与资源确认':kind==='independent-implementation'?'当前独立实现':'尚未闭合的关系'));for(const f of selected){const part=el('details');part.dataset.coreDataFact=f.id;part.append(el('summary',f.id+' · '+f.from+' → '+f.to),el('p',f.classification),el('p',f.behavior),el('p','类型 / 持有 / 复制：'+f.representation),el('p','缓存 / 失效：'+f.cache),el('p','退役 / 释放：'+f.release));for(const r of f.refs||[]){if(r.binaryIdentity||r.artifact||r.reaEvidence)part.append(el('p',[r.artifact,r.binaryIdentity,r.reaEvidence].filter(Boolean).join(' · ')));showRef(r,part);}for(const u of f.unknowns||[])part.append(el('p','待核：'+u));const a=el('a','在数据页签定位并展开同一事实 ↗');a.href='../framework-architecture.html#data-design/fact/'+encodeURIComponent(f.id);part.append(a);section.append(part);rendered.add(f.id);}}host.append(section);return rendered;}
function showDataTopics(region,host){const renderedDataFacts=showRegionDataContext(region,host);if(['workflow','all'].includes(region)&&model.core.dataArchitecture.entryContext.groupCapabilities)renderGroupCapabilities(host,model.core.dataArchitecture.entryContext.groupCapabilities,el);const picks={menu:['model','persistence','boundary'],toolbar:['runtime','publication','persistence','boundary'],toolbox:['model'],workflow:['model','binding','runtime','history'],results:['runtime','publication','image'],imagebox:['image'], 'history-help':['history'],status:['publication'],all:['structure','flows','model','binding','runtime','image','publication','history','persistence','boundary']};const names={structure:'数据结构与字段',flows:'数据传递总图',model:'方案/节点结构',binding:'类型/订阅/索引',runtime:'单轮值与执行结果',image:'图像/ROI/显示载荷',publication:'回调/缓存/线程',history:'历史与快照',persistence:'保存/格式/资源',boundary:'消息/ABI/返回值'};const box=el('section');box.append(el('h3','从这个界面位置看数据'));for(const id of picks[region]||[]){const a=el('a',names[id]+' ↗');a.href=model.core.dataArchitecture.path+'#'+id;box.append(a,el('br'))}const trackIds=region==='all'?['parameters','images','module-results']:['workflow','menu'].includes(region)?['parameters']:region==='imagebox'?['images']:region==='results'?['images','module-results']:['toolbar','status'].includes(region)?['parameters','module-results']:[];for(const tid of trackIds){const t=model.core.dataArchitecture.lifecycle.tracks.find(t=>t.id===tid);box.append(el('h3',t.title));for(const id of t.factIds){if(renderedDataFacts.has(id))continue;const f=model.core.dataArchitecture.lifecycle.facts.find(f=>f.id===id),part=el('details');part.append(el('summary',id+' · '+f.from+' → '+f.to),el('p',f.classification),el('p','表示/复制：'+f.representation),el('p','缓存/失效：'+f.cache),el('p','释放：'+f.release),el('p',f.behavior));for(const r of f.refs)showRef(r,part);for(const u of f.unknowns)part.append(el('p','待追：'+u));box.append(part)}}host.append(box)}
const baseShowRegion=showRegion;showRegion=function(id){baseShowRegion(id);showCoreBranches(b=>b.regions.includes(id),document.getElementById('detail'))};
const layerBox=document.getElementById('coreTopLayers');layerBox.className='corelayers';for(const n of model.core.topDown.nodes){const b=el('button',n.label+' ↓');b.onclick=()=>showCoreTop(n);layerBox.append(b)}
const up=model.core.bottomUp,upNodes=new Map(up.nodes.map(n=>[n.id,n])),upBox=document.getElementById('coreUpstream');upBox.className='coreup';upBox.append(el('h2','工具UI向上追溯'),el('p',up.scope));const pluginDetailLink=el('a','工具插件专页：全目录、算法对比与优先级 ↗');pluginDetailLink.href=model.core.toolPluginDetail.path;upBox.append(pluginDetailLink);function showUpEdge(e){const d=document.getElementById('detail');d.replaceChildren(el('h2',e.id+' · '+upNodes.get(e.from).label+' → '+upNodes.get(e.to).label),el('p',e.classification+' / '+e.relation),el('p','分析方向：'+e.condition),el('p',e.behavior),el('p','这是取证/追溯关系；具体原始调用方向保留在引用里，不能反向解释为运行调用。'));coreLinks(e.parents,d);for(const r of e.refs||[])showRef(r,d);showUpstreamRelated([e.from,e.to],d)}for(const n of up.nodes){const b=el('button');b.append(el('b',n.label),el('small',n.detail||''));b.onclick=()=>{const d=document.getElementById('detail');d.replaceChildren(el('h2','向上追溯 › '+n.label),el('p',n.detail||''));showUpstreamRelated([n.id],d);for(const e of up.edges.filter(e=>e.from===n.id||e.to===n.id)){const a=el('button',e.id+' · '+upNodes.get(e.from).label+' → '+upNodes.get(e.to).label+' · '+e.classification);a.onclick=()=>showUpEdge(e);d.append(a)}};upBox.append(b)}
const scopeBox=document.getElementById('coreScope');scopeBox.className='coreScope';const ownerDetails=el('details');ownerDetails.append(el('summary','两项目职责、汇合证据与未知边界'));for(const owner of model.core.ownership){ownerDetails.append(el('b',owner.project),el('p',owner.role));for(const r of owner.refs)showRef(r,ownerDetails)}ownerDetails.append(el('p',model.core.junctionPolicy.meaning));for(const s of model.core.junctionPolicy.requiredEvidence)ownerDetails.append(el('p','汇合需要：'+s));const boundary=el('a','职责原文 / 合同请求');boundary.href='../PLUGIN-FRAMEWORK-BOUNDARY.md';ownerDetails.append(boundary);scopeBox.append(ownerDetails);const resourceLink=el('a','资源范围对账：五个完整载体清单与其余部分资源记录 ↗');resourceLink.href=model.core.supplemental.resourceScope.path;scopeBox.append(resourceLink,el('p','234个BAML键属于五个选定程序集；原件资源盘点、离线解码、活绑定和完整入口分别记录。不能由键数量推断入口完整。'));
function coreMode(bottom){document.getElementById('downScopeNote').hidden=bottom;document.getElementById('mainAreaPane').hidden=bottom;document.getElementById('coreTopLayers').hidden=bottom;upBox.hidden=!bottom;document.getElementById('bottomUpEntry').setAttribute('aria-pressed',String(bottom));document.getElementById('topDownEntry').setAttribute('aria-pressed',String(!bottom));if(bottom){history.replaceState(null,'','#plugin-ui');if(up.edges.length)showUpEdge(up.edges[0])}else document.getElementById('mainRoot').click()}
function routeCoreHash(hash){if(hash.startsWith('#menu-entry/')||hash.startsWith('#menu-deferred/')){coreMode(false);history.replaceState(null,'',hash);return true}if(hash==='#plugin-ui'){coreMode(true);return true}const layer=model.core.topDown.nodes.find(n=>'#'+n.id===hash);if(layer){coreMode(false);showCoreTop(layer);return true}const match=/^#audit\/([^/]+)\/([^/]+)$/.exec(hash);if(match){let branchId,findingId;try{branchId=decodeURIComponent(match[1]);findingId=decodeURIComponent(match[2])}catch{return false}const b=model.core.supplemental.branches.find(b=>b.id===branchId),e=b?.findings.find(e=>e.id===findingId);if(!b||!e)return false;coreMode(false);showCoreFinding(b,e);return true}const region=model.regions.find(r=>'#'+r.id===hash);if(region){coreMode(false);showRegion(region.id);return true}if(hash==='#runtime-mode'){coreMode(false);document.getElementById('runtimeMode').click();return true}if(hash==='#main'||!hash){coreMode(false);return true}return false}
document.getElementById('topDownEntry').onclick=()=>coreMode(false);document.getElementById('bottomUpEntry').onclick=()=>coreMode(true);addEventListener('hashchange',()=>{if(!routeCoreHash(location.hash))coreMode(false)});if(!routeCoreHash(requestedCoreHash))coreMode(false);
